WITH fixes(slug,pos,why) AS (VALUES ('penal-confissao-sumulas-545-630',9,'A confissão espontânea perante a autoridade é circunstância legalmente atenuante (CP, art. 65, III, d), mas a palavra ''sempre'' exige cuidado: o reconhecimento e seus efeitos na dosimetria dependem do caso, e a atenuante não autoriza, por si só, pena abaixo do mínimo legal conforme a Súmula 231 do STJ.'),('legislacao-quimicos-revisao',2,'Correto. A Lei 10.357/2001 prevê controle de produtos químicos e admite atualização da relação dos produtos sujeitos à fiscalização por ato normativo competente. Em prova, diferencie a lei que institui o controle da portaria que detalha a lista.'),('legislacao-quimicos-revisao',6,'Correto. O art. 11 da Lei 10.357/2001 trata da comunicação à Polícia Federal de suspeita de desvio de produto químico controlado, no prazo legal de 24 horas. Atenção ao termo ''suspeita'': não é preciso esperar confirmação do desvio.'),('legislacao-quimicos-revisao',7,'Correto. A Lei 10.357/2001 disciplina cadastro e autorização para atividades com produtos químicos controlados, inclusive hipóteses eventuais. A exigência concreta depende do enquadramento da atividade e do produto.'),('legislacao-menor-potencial-ofensivo-revisao',5,'Correto. A capacitação para emprego de instrumentos de menor potencial ofensivo deve preparar o agente para seu uso adequado, observando técnicas, limites e prevenção de lesões. Não basta simplesmente entregar o equipamento ao servidor.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;